    if (role !== 'hod' && !departments.some(d => d.name === person.department && users.some(u => u.id === d.hodId && u.active && u.role === 'hod' && u.departmentId === d.id))) { notify('Assign an active department HOD before submitting'); return }
    const request: EventRequest = { id: `CH-${Math.max(...requests.map(r => Number(r.id.split('-')[1]))) + 1}`, title: form.title.trim(), requester: person.name, role, department: person.department, date: form.date, startTime: form.startTime, endTime: form.endTime, attendees: Number(form.attendees), venueId: chosenVenue.id, included: chosenVenue.included.map(item => ({ ...item })), extras, description: form.description.trim(), status: role === 'hod' ? 'pending-admin' : 'pending-hod', created: dateFromNow(0) }
    setRequests(prev => [request, ...prev]); setForm({ title: '', date: '', startTime: '', endTime: '', attendees: '', venueId: '', description: '' }); setExtras([]); navigate('requests'); notify(`${request.id} submitted to ${role === 'hod' ? 'Campus Admin' : `${person.department} HOD`}`)
